@sig trait CSA_Enable_Delivery_Thread_Api {
  def id: Art.BridgeId
  def ap_on_in_Id : Art.PortId
  def ap_on_out_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var ap_on_out: FAA_Autopilot_Engagement.AP_On_Indication.Type = $

  def put_ap_on_out(value : FAA_Autopilot_Engagement.AP_On_Indication.Type) : Unit = {
    Contract(
      Modifies(ap_on_out),
      Ensures(
        ap_on_out == value
      )
    )
    Spec {
      ap_on_out = value
    }

    Art.putValue(ap_on_out_Id, FAA_Autopilot_Engagement.AP_On_Indication_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class CSA_Enable_Delivery_Thread_Initialization_Api (
  val id: Art.BridgeId,
  val ap_on_in_Id : Art.PortId,
  val ap_on_out_Id : Art.PortId) extends CSA_Enable_Delivery_Thread_Api

@datatype class CSA_Enable_Delivery_Thread_Operational_Api (
  val id: Art.BridgeId,
  val ap_on_in_Id : Art.PortId,
  val ap_on_out_Id : Art.PortId) extends CSA_Enable_Delivery_Thread_Api {

  // Logika spec var representing port state for incoming data port
  @spec var ap_on_in: FAA_Autopilot_Engagement.AP_On_Indication.Type = $

  def get_ap_on_in() : Option[FAA_Autopilot_Engagement.AP_On_Indication.Type] = {
    Contract(
      Ensures(
        Res == Some(ap_on_in)
      )
    )
    val value : Option[FAA_Autopilot_Engagement.AP_On_Indication.Type] = Art.getValue(ap_on_in_Id) match {
      case Some(FAA_Autopilot_Engagement.AP_On_Indication_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port ap_on_in.  Expecting 'FAA_Autopilot_Engagement.AP_On_Indication_Payload' but received ${v}")
        None[FAA_Autopilot_Engagement.AP_On_Indication.Type]()
      case _ => None[FAA_Autopilot_Engagement.AP_On_Indication.Type]()
    }
    return value
  }
}
